 or (select count(*) from public.award_entries e join public.award_events v on v.id=e.award_event_id where v.award_organization='tga' and v.year between 2014 and 2025) <> 1773
 or (select count(*) from public.award_entries e join public.award_events v on v.id=e.award_event_id where v.award_organization='tga' and v.year between 2014 and 2025 and e.status='winner') <> 365
